import json

def S(sid, name, doc, ep, access="api", fmt="json", auth="none", lat="unklar", hist="unklar", lic="unklar", note="", rl="unklar", cost="free"):
    return {"source_id": sid, "name": name, "doc_url": doc, "endpoint": ep, "access": access, "format": fmt,
            "auth": auth, "cost": cost, "update_latency": lat, "history": hist, "rate_limit": rl,
            "license": lic, "verified": False, "sample_note": note}

def G(id_, name, plain, dom, ev, rat, d, lt, banal, man, pr, srcs, notes=""):
    return {"id": "cyber." + id_, "name_de": name, "plain_de": plain, "domain": dom, "evidence_class": ev,
            "rationale": rat, "direction": d, "lead_time": lt, "banal_causes": banal, "manipulability": man,
            "priority": pr, "sources": srcs, "notes": notes}

